//! Markdown documentation generator (`sheaf docs`) derived from Clap command metadata.

use clap::CommandFactory;
use std::fmt::Write as _;

use crate::cli::Cli;

/// Generates the complete Markdown documentation for all Sheaf CLI commands and options.
pub fn generate_cli_markdown() -> String {
    let mut out = String::new();
    let root = Cli::command();

    let _ = writeln!(out, "# Sheaf CLI Reference\n");
    let _ = writeln!(
        out,
        "> **Note:** This documentation is automatically generated from the Clap command definition.\n> Do not edit this file by hand. Update it with `UPDATE_DOCS=1 cargo test --test docs_sync_test`.\n"
    );

    let _ = writeln!(out, "## Table of Contents\n");
    for sub in root.get_subcommands() {
        if sub.is_hide_set() {
            continue;
        }
        let _ = writeln!(
            out,
            "- [`sheaf {}`](#sheaf-{})",
            sub.get_name(),
            sub.get_name()
        );
    }
    let _ = writeln!(out);

    let _ = writeln!(out, "## Global Options\n");
    let _ = writeln!(
        out,
        "These options are supported across all `sheaf` subcommands:\n"
    );
    let _ = writeln!(out, "| Option | Description |");
    let _ = writeln!(out, "| :--- | :--- |");
    let _ = writeln!(
        out,
        "| `--json` | Output a single JSON envelope object on stdout |"
    );
    let _ = writeln!(
        out,
        "| `--dry-run` | Validate inputs and compute execution plan without writing files |"
    );
    let _ = writeln!(out, "| `--force` | Overwrite existing output files |");
    let _ = writeln!(
        out,
        "| `-q, --quiet` | Suppress human-readable output except errors |"
    );
    let _ = writeln!(
        out,
        "| `-v, --verbose` | Emit verbose debug logs on stderr |"
    );
    let _ = writeln!(
        out,
        "| `--progress <MODE>` | Progress output mode on stderr (`none`, `human`, `json`) |"
    );
    let _ = writeln!(
        out,
        "| `--no-color` | Disable colored console output (also respects `NO_COLOR`) |\n"
    );

    for sub in root.get_subcommands() {
        if sub.is_hide_set() {
            continue;
        }
        let name = sub.get_name();
        let _ = writeln!(out, "## `sheaf {}`\n", name);
        if let Some(about) = sub.get_about() {
            let _ = writeln!(out, "{}\n", about);
        }

        let _ = writeln!(out, "### Options & Arguments\n");
        let _ = writeln!(
            out,
            "| Option / Argument | Value | Required | Description |"
        );
        let _ = writeln!(out, "| :--- | :--- | :--- | :--- |");

        for arg in sub.get_arguments() {
            if arg.get_id() == "help" || arg.get_id() == "version" || arg.is_hide_set() {
                continue;
            }
            let name_str = if let Some(long) = arg.get_long() {
                if let Some(short) = arg.get_short() {
                    format!("`-{short}, --{long}`")
                } else {
                    format!("`--{long}`")
                }
            } else {
                format!("`<{}>`", arg.get_id())
            };
            let value_str = arg
                .get_value_names()
                .and_then(|v| v.first().map(|s| format!("`<{s}>`")))
                .unwrap_or_else(|| "-".to_string());
            let required_str = if arg.is_required_set() { "Yes" } else { "No" };
            let help_str = arg
                .get_help()
                .map(|h| h.to_string().replace('\n', " "))
                .unwrap_or_default();

            let _ = writeln!(
                out,
                "| {name_str} | {value_str} | {required_str} | {help_str} |"
            );
        }
        let _ = writeln!(out);

        if let Some(after_help) = sub.get_after_help() {
            let _ = writeln!(out, "### Examples\n");
            let _ = writeln!(out, "```bash");
            for line in after_help.to_string().lines() {
                if line.starts_with("Examples:") {
                    continue;
                }
                let trimmed = line.trim();
                if !trimmed.is_empty() {
                    let _ = writeln!(out, "{trimmed}");
                }
            }
            let _ = writeln!(out, "```\n");
        }
    }

    out
}

use crate::cli::DocsArgs;
use crate::commands::{Command, Ctx, Outcome};
use serde::Serialize;
use sheaf_core::SheafError;

/// Empty report for docs command.
#[derive(Debug, Clone, Serialize)]
pub struct DocsReport {
    /// Markdown documentation text.
    pub markdown: String,
}

impl Command for DocsArgs {
    type Report = DocsReport;

    fn name(&self) -> &'static str {
        "docs"
    }

    fn run(&self, _ctx: &Ctx) -> Result<Outcome<Self::Report>, SheafError> {
        let markdown = generate_cli_markdown();
        Ok(Outcome {
            report: DocsReport { markdown },
            warnings: Vec::new(),
            dry_run: false,
            failure: None,
        })
    }

    fn format_human(&self, report: &Self::Report, _dry_run: bool) -> String {
        report.markdown.clone()
    }
}
